import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry } = ctx.THREE;

  // Container for the badge
  const root = new Group();

  // Geometry – size based on typical badge proportions
  const width = 0.8;
  const height = 0.3;
  const geometry = new PlaneGeometry(width, height);

  // Material – start without texture, will be set async
  const material = new MeshBasicNodeMaterial({
    transparent: true,
    depthWrite: false,
  });

  // Mesh
  const plane = new Mesh(geometry, material);
  root.add(plane);

  // Load texture asynchronously
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      material.map = tex;
      material.needsUpdate = true;
    });
  }

  // Keep track of active GSAP tweens for cleanup
  const activeTweens = [];

  // Helper to kill all stored tweens
  const killTweens = () => {
    activeTweens.forEach((t) => t && t.kill && t.kill());
    activeTweens.length = 0;
  };

  // Event handlers
  root.userData.handlers = {
    hover: (enter) => {
      killTweens();
      if (enter) {
        const t = gsap.to(plane.position, {
          y: 0.15,
          duration: 0.7,
          ease: 'power3.out',
        });
        activeTweens.push(t);
      } else {
        const t = gsap.to(plane.position, {
          y: 0,
          duration: 0.7,
          ease: 'power3.out',
        });
        activeTweens.push(t);
      }
    },
    click: () => {
      killTweens();
      const t = gsap.to(plane.scale, {
        x: 0.97,
        y: 0.97,
        z: 0.97,
        duration: 0.12,
        ease: 'back.out',
      });
      activeTweens.push(t);
      ctx.emit('hub-pricing.select', {});
    },
  };

  // Cleanup routine
  root.userData.cleanup = () => {
    killTweens();
    // Dispose geometry and material
    geometry.dispose();
    material.dispose();
    // Dispose texture if loaded
    if (material.map) {
      material.map.dispose();
    }
  };

  return root;
}
